int visited[1010][7];

int dx[] = {0,0,1,-1};
int dy[] = {1,-1,0,0};

void bfs(int sr, int sc) {
    // Simple BFS
    int *qr = malloc(n*7*sizeof(int));
    int *qc = malloc(n*7*sizeof(int));
    int head=0, tail=0;
    qr[tail]=sr; qc[tail]=sc; tail++;
    visited[sr][sc]=1;
    while(head<tail) {
        int r=qr[head], c=qc[head]; head++;
        for(int d=0;d<4;d++){
            int nr=r+dx[d], nc=c+dy[d];
            if(nr>=0&&nr<n&&nc>=0&&nc<7&&!visited[nr][nc]&&!grid[nr][nc]){
                visited[nr][nc]=1;
                qr[tail]=nr; qc[tail]=nc; tail++;
            }
        }
    }
    free(qr); free(qc);
}

