static ll gcdll(ll a, ll b) {
    while (b) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a >= 0 ? a : -a;
}

static ll exgcd(ll a, ll b, ll *x, ll *y) {
    if (b == 0) {
        *x = 1;
        *y = 0;
        return a;
    }
    ll x1, y1;
    ll g = exgcd(b, a % b, &x1, &y1);
    *x = y1;
    *y = x1 - (a / b) * y1;
    return g;
}

static ll modinv(ll a, ll mod) {
    ll x, y;
    ll g = exgcd(a, mod, &x, &y);
    if (g != 1) return -1;
    x %= mod;
    if (x < 0) x += mod;
    return x;
}

static ll crt_pair(ll r1, ll m1, ll r2, ll m2, ll *lcm_out) {
    ll g = gcdll(m1, m2);
    if ((r2 - r1) % g != 0) return -1;
    ll m1g = m1 / g, m2g = m2 / g;
    ll inv = modinv((m1g % m2g + m2g) % m2g, m2g);
    ll t = ((r2 - r1) / g) % m2g;
    if (t < 0) t += m2g;
    t = (__int128)t * inv % m2g;
    ll lcm = m1 / g * m2;
    ll res = (r1 + (__int128)m1 * t) % lcm;
    if (res < 0) res += lcm;
    *lcm_out = lcm;
    return res;
}

static int lower_bound_ll(ll *a, int n, ll x) {
    int l = 0, r = n;
    while (l < r) {
        int mid = (l + r) >> 1;
        if (a[mid] < x) l = mid + 1;
        else r = mid;
    }
    return l;
}

static int cmp_ll(const void *p1, const void *p2) {
    ll a = *(const ll*)p1;
    ll b = *(const ll*)p2;
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
}

