#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    int q;
    cin >> n >> m >> q;

    vector<long long> a(q);
    for (int i = 0; i < q; ++i) cin >> a[i];

    // A cell (r, c) (1-indexed), value = 7r + c - 8.
    // It is black iff value % m is in the given set.
    //
    // Color pattern depends only on value modulo m, and moving:
    // right changes value by +1, down changes value by +7.
    //
    // Therefore the whole infinite pattern is periodic in rows with period:
    // smallest T such that 7T ≡ 0 (mod m), i.e. T = m / gcd(m, 7).
    //
    // Since columns are only 7, we can build one period of rows and connect
    // components through repeated identical layers.

    vector<int> bad(m, 0);
    for (long long x : a) bad[x % m] = 1;

    long long g = std::gcd(m, 7LL);
    long long T = m / g; // row period

    // If n is huge, only first T rows matter structurally; repetitions can only
    // merge components between consecutive copies of the same period.
    int rows = (int)min(n, T);

    vector<vector<int>> white(rows, vector<int>(7, 0));
    for (int i = 0; i < rows; ++i) {
        long long base = (7LL * (i + 1) - 7) % m; // value at column 1: 7(i+1)+1-8 = 7i
        for (int j = 0; j < 7; ++j) {
            long long rem = (base + j) % m;
            white[i][j] = !bad[rem];
        }
    }

    // DSU on cells in one period
    int V = rows * 7;
    vector<int> p(V), sz(V, 1);
    iota(p.begin(), p.end(), 0);

    function<int(int)> find = [&](int x) {
        return p[x] == x ? x : p[x] = find(p[x]);
    };
    auto unite = [&](int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
    };

    auto id = [&](int r, int c) { return r * 7 + c; };

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < 7; ++j) if (white[i][j]) {
            if (j + 1 < 7 && white[i][j + 1]) unite(id(i, j), id(i, j + 1));
            if (i + 1 < rows && white[i + 1][j]) unite(id(i, j), id(i + 1, j));
        }
    }

    // Count components in the first block
    set<int> comps;
    for (int i = 0; i < rows; ++i)
        for (int j = 0; j < 7; ++j)
            if (white[i][j])
                comps.insert(find(id(i, j)));

    long long ans_first = (long long)comps.size();

    // If n <= T, done.
    if (n <= T) {
        cout << ans_first << '\n';
        return 0;
    }

    // For repeated blocks of height T:
    // every block is identical. When appending another identical block,
    // the number of components changes only by adding components of the new block
    // and subtracting those merged through the boundary.
    //
    // To know whether growth continues, we examine one full period T.
    // Since row T connects to row 1 of next block with same pattern.

    // Rebuild for full period T if rows < T only when n > T impossible.
    rows = (int)T;
    white.assign(rows, vector<int>(7, 0));
    for (int i = 0; i < rows; ++i) {
        long long base = (7LL * (i + 1) - 7) % m;
        for (int j = 0; j < 7; ++j) {
            long long rem = (base + j) % m;
            white[i][j] = !bad[rem];
        }
    }

    V = rows * 7;
    p.assign(V, 0);
    sz.assign(V, 1);
    iota(p.begin(), p.end(), 0);

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < 7; ++j) if (white[i][j]) {
            if (j + 1 < 7 && white[i][j + 1]) unite(id(i, j), id(i, j + 1));
            if (i + 1 < rows && white[i + 1][j]) unite(id(i, j), id(i + 1, j));
        }
    }

    comps.clear();
    for (int i = 0; i < rows; ++i)
        for (int j = 0; j < 7; ++j)
            if (white[i][j])
                comps.insert(find(id(i, j)));
    long long C = comps.size(); // components inside one block

    // Determine merges between consecutive blocks:
    // only possible vertically between last row of one block and first row of next.
    // Build bipartite connections between components touching bottom/top rows.
    set<pair<int,int>> edges;
    for (int j = 0; j < 7; ++j) {
        if (white[rows - 1][j] && white[0][j]) {
            int aroot = find(id(rows - 1, j));
            int broot = find(id(0, j));
            edges.insert({aroot, broot});
        }
    }

    // Number of connected components in two consecutive blocks:
    // C + C - (#successful unions among block-components via boundary)
    // We can compute delta added by each extra block as number of components
    // in new block after identifying boundary-linked ones.
    //
    // Compress component ids of one block.
    vector<int> roots(comps.begin(), comps.end());
    unordered_map<int,int> mp;
    for (int i = 0; i < (int)roots.size(); ++i) mp[roots[i]] = i;
    int K = roots.size();

    vector<int> pp(2 * K), ss(2 * K, 1);
    iota(pp.begin(), pp.end(), 0);
    function<int(int)> f2 = [&](int x) { return pp[x] == x ? x : pp[x] = f2(pp[x]); };
    auto u2 = [&](int a, int b) {
        a = f2(a); b = f2(b);
        if (a == b) return false;
        if (ss[a] < ss[b]) swap(a, b);
        pp[b] = a;
        ss[a] += ss[b];
        return true;
    };

    long long merged = 0;
    for (auto [a, b] : edges) {
        int x = mp[a];
        int y = mp[b] + K; // second block copy
        if (u2(x, y)) merged++;
    }

    long long delta = C - merged; // each additional full block increases answer by this

    long long fullBlocks = n / T;
    long long remRows = n % T;

    // Start with first full block
    long long ans = C;
    if (fullBlocks >= 2) ans += (fullBlocks - 1) * delta;

    if (remRows == 0) {
        cout << ans << '\n';
        return 0;
    }

    // Handle remaining prefix of next block of height remRows.
    int r2 = (int)remRows;

    // Components in the remainder prefix alone
    int V2 = r2 * 7;
    vector<int> p3(V2), s3(V2, 1);
    iota(p3.begin(), p3.end(), 0);
    function<int(int)> f3 = [&](int x) { return p3[x] == x ? x : p3[x] = f3(p3[x]); };
    auto u3 = [&](int a, int b) {
        a = f3(a); b = f3(b);
        if (a == b) return;
        if (s3[a] < s3[b]) swap(a, b);
        p3[b] = a;
        s3[a] += s3[b];
    };
    auto id2 = [&](int r, int c) { return r * 7 + c; };

    for (int i = 0; i < r2; ++i) {
        for (int j = 0; j < 7; ++j) if (white[i][j]) {
            if (j + 1 < 7 && white[i][j + 1]) u3(id2(i, j), id2(i, j + 1));
            if (i + 1 < r2 && white[i + 1][j]) u3(id2(i, j), id2(i + 1, j));
        }
    }

    set<int> remCompRoots;
    for (int i = 0; i < r2; ++i)
        for (int j = 0; j < 7; ++j)
            if (white[i][j])
                remCompRoots.insert(f3(id2(i, j)));

    long long CR = remCompRoots.size();

    // Count merges between previous full block bottom row and this remainder top row.
    unordered_map<int,int> remMap;
    int idx = 0;
    for (int x : remCompRoots) remMap[x] = idx++;

    vector<int> pp4(K + idx), ss4(K + idx, 1);
    iota(pp4.begin(), pp4.end(), 0);
    function<int(int)> f4 = [&](int x) { return pp4[x] == x ? x : pp4[x] = f4(pp4[x]); };
    auto u4 = [&](int a, int b) {
        a = f4(a); b = f4(b);
        if (a == b) return false;
        if (ss4[a] < ss4[b]) swap(a, b);
        pp4[b] = a;
        ss4[a] += ss4[b];
        return true;
    };

    long long merged2 = 0;
    for (int j = 0; j < 7; ++j) {
        if (white[rows - 1][j] && white[0][j]) {
            int aroot = find(id(rows - 1, j));
            int broot = f3(id2(0, j));
            if (u4(mp[aroot], K + remMap[broot])) merged2++;
        }
    }

    ans += CR - merged2;
    cout << ans << '\n';
    return 0;
}

