public class Main {
    static final int COLS = 7;
    static int[] parent, size;
    static boolean[][] black;

    static int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    static void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) {
            int tmp = ra; ra = rb; rb = tmp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }

    static int id(int r, int c) {
        return r * COLS + c;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int q = Integer.parseInt(st.nextToken());

        int total = n * COLS;
        black = new boolean[n][COLS];
        parent = new int[total];
        size = new int[total];
        for (int i = 0; i < total; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        int whiteCount = total;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int op = 0; op < q; op++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int ri = Integer.parseInt(st.nextToken());

            // Find cells to blacken
            List<int[]> toBlacken = new ArrayList<>();
            for (int col = 0; col < COLS; col++) {
                int val = 7 * ri + col - 8;
                if (val % m == a && !black[ri][col]) {
                    toBlacken.add(new int[]{ri, col});
                }
            }

            for (int[] cell : toBlacken) {
                int r = cell[0], c = cell[1];
                black[r][c] = true;
                whiteCount--;
                int idx = id(r, c);
                // Disconnect by not unioning; we just remove node from white components.
                // But since we never added it yet to union for white, we need to handle properly:
                // Instead, we maintain white connectivity by union-find on white cells only.
                // We'll rebuild adjacency removal by marking black and not counting it.
                // Better approach: initially union all white, then when blackening, we just mark black
                // and reduce component count if needed. Simpler: after all ops, count components.
            }
        }

        // Build UF for white cells only
        parent = new int[total];
        size = new int[total];
        for (int i = 0; i < total; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        int components = 0;
        boolean[] visited = new boolean[total];
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < COLS; c++) {
                if (black[r][c]) continue;
                int idx = id(r, c);
                if (visited[idx]) continue;
                // BFS to mark component
                Queue<Integer> queue = new LinkedList<>();
                queue.add(idx);
                visited[idx] = true;
                components++;
                while (!queue.isEmpty()) {
                    int cur = queue.poll();
                    int cr = cur / COLS;
                    int cc = cur % COLS;
                    for (int d = 0; d < 4; d++) {
                        int nr = cr + dr[d];
                        int nc = cc + dc[d];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < COLS && !black[nr][nc]) {
                            int nid = id(nr, nc);
                            if (!visited[nid]) {
                                visited[nid] = true;
                                queue.add(nid);
                            }
                        }
                    }
                }
            }
        }

        System.out.println(components);
    }
}

import java.io.*;
import java.util.*;

/*
 * Calendar painting / counting white connected components
 *
 * Grid:
 *   n rows, 7 columns
 *   cell (i, j) contains value 7*i + j - 8   (1-indexed)
 *
 * For each query residue a (mod m), all cells whose value % m == a are painted black.
 * After all q residues are applied, count connected components of remaining white cells
 * using 4-neighborhood.
 *
 * Key observation:
 *   A cell value is x. Black iff x mod m belongs to a forbidden set S.
 *   Therefore color depends only on x mod m.
 *
 * Along the calendar:
 *   horizontal neighbor differs by +1
 *   vertical neighbor differs by +7
 *
 * So if we know white/black status for residues modulo m, the infinite pattern over values
 * is periodic modulo m. We process rows by transitions of the 7-cell row mask.
 *
 * Let row i contain values base_i + 0..6 where base_i = 7*i - 7.
 * Row mask for row i is determined by residues (base_i + k) mod m.
 * Since base_{i+1} = base_i + 7, row masks evolve by shifting start residue by +7 mod m.
 * Period length over rows is L = m / gcd(m,7).
 *
 * We build DSU over white cells in one period of L rows and count:
 *   - components entirely inside the period graph
 *   - how these components connect from bottom of one period to top of next period
 *
 * Then for n rows = t full periods + rem:
 *   repeated composition over periods is simple because each period is identical.
 *
 * More directly, we use a transfer on component labels of a 7-cell frontier.
 * Since width is only 7, number of states is manageable.
 *
 * State = canonical partition of white cells in current row induced by connectivity
 *         within processed prefix, plus row mask.
 * Transition row by row standard profile DP, while counting component births and merges.
 *
 * Since row masks are deterministic, we only need to propagate one map of possible states;
 * in fact deterministically from empty start there is only one state per row progression.
 * We track total number of finished components.
 *
 * For very large n, row masks are periodic, so we binary-lift the deterministic transition
 * over one period using functional graph style on finite states discovered from period start.
 *
 * Simpler still: because transition is deterministic, simulate one period from a given state.
 * Build function F on states after L rows. Then answer after t periods by binary lifting F,
 * and finally process rem rows directly.
 *
 * Width 7 => state count small.
 */

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static final int W = 7;

    static class State {
        // labels[0..6]: 0 for black, positive canonical labels for white cells in current row
        final byte[] lab;

        State(byte[] a) {
            this.lab = a;
        }

        @Override
        public boolean equals(Object o) {
            if (!(o instanceof State)) return false;
            return Arrays.equals(lab, ((State) o).lab);
        }

        @Override
        public int hashCode() {
            return Arrays.hashCode(lab);
        }
    }

    static class TransResult {
        State next;
        long add; // number of components closed during this row addition
        TransResult(State n, long a) { next = n; add = a; }
    }

    static boolean[] black; // residue black
    static long m;

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static int rowMask(long startResidue) {
        int mask = 0;
        long r = startResidue % m;
        for (int j = 0; j < W; j++) {
            if (!black[(int) r]) mask |= (1 << j); // white bit
            r++;
            if (r == m) r = 0;
        }
        return mask;
    }

    static State canonical(byte[] arr) {
        int[] map = new int[W + 1];
        byte nxt = 1;
        byte[] b = new byte[W];
        for (int i = 0; i < W; i++) {
            int x = arr[i];
            if (x == 0) continue;
            if (map[x] == 0) map[x] = nxt++;
            b[i] = (byte) map[x];
        }
        return new State(b);
    }

    static TransResult advance(State s, int whiteMask) {
        // Old row labels
        byte[] old = s.lab;

        // DSU over old labels + new cells
        // old labels max 7, new nodes 7
        int MAX = 20;
        int[] p = new int[MAX];
        for (int i = 0; i < MAX; i++) p[i] = i;

        int find(int x) {
            while (p[x] != x) {
                p[x] = p[p[x]];
                x = p[x];
            }
            return x;
        }

        class UF {
            int find(int x) {
                int y = x;
                while (p[y] != y) y = p[y];
                while (p[x] != x) {
                    int t = p[x];
                    p[x] = y;
                    x = t;
                }
                return y;
            }
            void union(int a, int b) {
                a = find(a); b = find(b);
                if (a != b) p[a] = b;
            }
        }
        UF uf = new UF();

        // old labels are 1..k
        int k = 0;
        for (byte x : old) k = Math.max(k, x);

        int[] nodeNew = new int[W];
        Arrays.fill(nodeNew, -1);
        int nextId = k + 1;

        // create new white cells
        for (int j = 0; j < W; j++) {
            if (((whiteMask >> j) & 1) == 1) {
                nodeNew[j] = nextId++;
            }
        }

        // horizontal unions in new row
        for (int j = 0; j + 1 < W; j++) {
            if (nodeNew[j] != -1 && nodeNew[j + 1] != -1) {
                uf.union(nodeNew[j], nodeNew[j + 1]);
            }
        }

        // vertical unions with old row
        for (int j = 0; j < W; j++) {
            if (nodeNew[j] != -1 && old[j] != 0) {
                uf.union(nodeNew[j], old[j]);
            }
        }

        // old components that survive to next frontier
        boolean[] oldPresent = new boolean[k + 1];
        for (int j = 0; j < W; j++) if (old[j] != 0) oldPresent[old[j]] = true;

        boolean[] survives = new boolean[k + 1];
        for (int j = 0; j < W; j++) {
            if (nodeNew[j] != -1) {
                int r = uf.find(nodeNew[j]);
                for (int lbl = 1; lbl <= k; lbl++) {
                    if (oldPresent[lbl] && uf.find(lbl) == r) survives[lbl] = true;
                }
            }
        }

        long add = 0;
        for (int lbl = 1; lbl <= k; lbl++) {
            if (oldPresent[lbl] && !survives[lbl]) add++;
        }

        // build next row labels from new row connectivity
        byte[] nxt = new byte[W];
        Map<Integer, Byte> mp = new HashMap<>();
        byte id = 1;
        for (int j = 0; j < W; j++) {
            if (nodeNew[j] != -1) {
                int r = uf.find(nodeNew[j]);
                Byte got = mp.get(r);
                if (got == null) {
                    got = id++;
                    mp.put(r, got);
                }
                nxt[j] = got;
            }
        }

        return new TransResult(new State(nxt), add);
    }

    static class PeriodJump {
        int to;
        long add;
        PeriodJump(int to, long add) { this.to = to; this.add = add; }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long n = fs.nextLong();
        m = fs.nextLong();
        int q = fs.nextInt();

        black = new boolean[(int) m];
        for (int i = 0; i < q; i++) {
            int a = (int) fs.nextLong();
            black[a] = true;
        }

        int L = (int) (m / gcd((int) m, 7));

        // Precompute row masks for one period
        int[] masks = new int[L];
        long start = 0; // row 1 starts at value 0
        for (int i = 0; i < L; i++) {
            masks[i] = rowMask(start);
            start += 7;
            start %= m;
        }

        // Discover deterministic period transition graph on states
        Map<State, Integer> idMap = new HashMap<>();
        ArrayList<State> states = new ArrayList<>();
        ArrayList<PeriodJump> period = new ArrayList<>();

        State empty = new State(new byte[W]);

        // function to get id
        java.util.function.Function<State, Integer> getId = st -> {
            Integer id = idMap.get(st);
            if (id == null) {
                id = states.size();
                idMap.put(st, id);
                states.add(st);
            }
            return id;
        };

        Queue<Integer> queue = new ArrayDeque<>();
        int emptyId = getId.apply(empty);
        queue.add(emptyId);

        while (!queue.isEmpty()) {
            int sid = queue.poll();
            State cur = states.get(sid);
            long add = 0;
            State now = cur;
            for (int i = 0; i < L; i++) {
                TransResult tr = advance(now, masks[i]);
                now = tr.next;
                add += tr.add;
            }
            int tid = getId.apply(now);
            while (period.size() <= sid) period.add(null);
            period.set(sid, new PeriodJump(tid, add));
            if (tid >= period.size() || period.get(tid) == null) queue.add(tid);
        }

        // binary lifting over period transitions
        int S = states.size();
        int LOG = 0;
        long full = n / L;
        while ((1L << LOG) <= full) LOG++;
        int[][] up = new int[LOG][S];
        long[][] sum = new long[LOG][S];
        for (int i = 0; i < S; i++) {
            up[0][i] = period.get(i).to;
            sum[0][i] = period.get(i).add;
        }
        for (int k = 1; k < LOG; k++) {
            for (int i = 0; i < S; i++) {
                up[k][i] = up[k - 1][up[k - 1][i]];
                sum[k][i] = sum[k - 1][i] + sum[k - 1][up[k - 1][i]];
            }
        }

        long ans = 0;
        int curId = emptyId;
        long t = full;
        int bit = 0;
        while (t > 0) {
            if ((t & 1L) != 0) {
                ans += sum[bit][curId];
                curId = up[bit][curId];
            }
            t >>= 1;
            bit++;
        }

        // remaining rows
        State cur = states.get(curId);
        int rem = (int) (n % L);
        for (int i = 0; i < rem; i++) {
            TransResult tr = advance(cur, masks[i]);
            cur = tr.next;
            ans += tr.add;
        }

        // remaining open components in final frontier
        boolean[] seen = new boolean[8];
        for (byte x : cur.lab) if (x != 0) seen[x] = true;
        for (int i = 1; i < seen.length; i++) if (seen[i]) ans++;

        System.out.println(ans);
    }
}
